import{at as e,it as t,t as n,vt as r}from"./chunks/framework.B7aBQbI5.js";var i=JSON.parse(`{"title":"Documentation and evidence","description":"","frontmatter":{},"headers":[],"relativePath":"documentation.md","filePath":"pages/documentation.md"}`),a={name:`documentation.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="documentation-and-evidence" tabindex="-1">Documentation and evidence <a class="header-anchor" href="#documentation-and-evidence" aria-label="Permalink to “Documentation and evidence”">​</a></h1><p>Read the behavior first, then open the implementation evidence when needed. Proposed work carries a visible status label and separate acceptance checks.</p><h2 id="page-shape-for-a-new-user" tabindex="-1">Page shape for a new user <a class="header-anchor" href="#page-shape-for-a-new-user" aria-label="Permalink to “Page shape for a new user”">​</a></h2><ol><li><strong>Outcome:</strong> what the user can do, in one sentence.</li><li><strong>Example:</strong> one executable example using released exports, or a clearly labelled proposed interaction.</li><li><strong>Contract:</strong> inputs, resulting state, lifetime, and who owns persistence.</li><li><strong>Evidence:</strong> source and fixture links; recorded results include command and revision.</li><li><strong>Limits:</strong> unsupported behavior and the decisions still open.</li></ol><p>For neighbor highlighting, the proposed introduction is: “Select a node to inspect its callers and dependencies. Hover previews the selection. Nearby hops stay bright; more distant hops fade.” The feature-status page links the existing traversal and the remaining renderer work. An executable usage example belongs here after the public API and its fixture exist.</p><h2 id="source-of-truth" tabindex="-1">Source of truth <a class="header-anchor" href="#source-of-truth" aria-label="Permalink to “Source of truth”">​</a></h2><table tabindex="0"><thead><tr><th>Content</th><th>Authoring location</th><th>Generated output</th></tr></thead><tbody><tr><td>Module purpose</td><td>First sentence of the module&#39;s leading line comment</td><td>API module table and section introduction</td></tr><tr><td>Export behavior</td><td>JSDoc beside the exported declaration</td><td>API prose beside its signature</td></tr><tr><td>Types and signatures</td><td>TypeScript declarations and compiler checker</td><td>API signature blocks</td></tr><tr><td>Public scope and reading order</td><td>grapht API generator&#39;s module list and barrel</td><td>Ordered module/export reference</td></tr><tr><td>Site navigation</td><td>Site content tree</td><td>VitePress sidebar, routes, page allow-list</td></tr><tr><td>Proposed work</td><td>Canonical plan files</td><td>Proposed-work pages with public source links</td></tr><tr><td>Task guide and implementation argument</td><td>Authored guide or plan</td><td>Short narrative with links to contracts and evidence</td></tr></tbody></table><p>The current generator consumes module-header prose and JSDoc summaries. It does not promise automatic rendering of every custom documentation tag. Guides supply the user task and the reasoning that declarations cannot express.</p><h2 id="comment-contract" tabindex="-1">Comment contract <a class="header-anchor" href="#comment-contract" aria-label="Permalink to “Comment contract”">​</a></h2><p>For a new or changed public module, write a leading sentence describing its behavior. For a new or changed export, put the behavioral contract in adjacent JSDoc: inputs/outputs, mutation or identity rules, resource lifetime, and important exclusions. Keep signatures in code; the generator reads them. Lifecycle teardown is named unsubscribe.</p><p>Examples in guides return composed streams to the application boundary. They must use actual exported APIs. Proposed examples and signatures remain visibly marked as sketches until implemented.</p><p>The frame, translation, and renderer modules demonstrate this convention. Existing modules can adopt it as they change; this page does not claim a completed documentation audit of every export.</p><h2 id="build-and-review" tabindex="-1">Build and review <a class="header-anchor" href="#build-and-review" aria-label="Permalink to “Build and review”">​</a></h2><p>The site content step regenerates the plans and API, checks documentation citations/exports, and renders the pages before VitePress builds. A docs-lint failure stops the build. Generated plan pages link to their canonical source; edit that source instead of the generated copy.</p><p>Keep arguments attached to decisions: requirement, existing capability, gap, selected behavior, alternatives or unresolved choice, and the observation that will decide acceptance. Keep performance claims tied to a reproducible measurement. A source link is evidence of implementation, a test result is evidence of the tested conditions, and a browser receipt is evidence of the exercised interaction.</p><p>Sources: <a href="https://github.com/hafley66/hafley-rxjs/blob/main/packages/docs-kit/scripts/api.mjs" target="_blank" rel="noreferrer">API generator</a>, <a href="https://github.com/hafley66/hafley-rxjs/blob/main/packages/docs-kit/scripts/docs.mjs" target="_blank" rel="noreferrer">docs checker</a>, <a href="https://github.com/hafley66/hafley-rxjs/blob/main/packages/grapht/site/content.ts" target="_blank" rel="noreferrer">site content tree</a>, <a href="https://github.com/hafley66/hafley-rxjs/blob/main/packages/grapht/scripts/6_plans.mjs" target="_blank" rel="noreferrer">plan publisher</a>.</p>`,16)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};